from rnn import train
from utils import get_prices, write_prices
import numpy as np

#write_prices()

values = get_prices()

SEQ_LEN = 300

def get_companies():
    with open("static/companies.txt", "r", encoding="utf-8") as file:
            tickers = [line.strip().upper() for line in file if line.strip()]
            return tickers

companies = get_companies()
relative_errors = []
i = 0
#while i < len(companies):
while i < 5:

    # sanity checks
    #print(values[companies[i]][-600:-300:])
    #print(values[companies[i]][-1])
    #print(len(values[companies[i]]))

    # leave last 300 out so training and test data won't mix, don't crash if some company has only short history
    try:
        model = train(values[companies[i]][:-300], sequence_length=SEQ_LEN, target_offset=300, epochs=50)
    except:
         i += 1
         continue

    # input is last 300 values before the test data
    to_predict_from = values[companies[i]][-600:-300:]
    # check for proper length
    assert len(to_predict_from) == SEQ_LEN
    # make prediction, should be the last available datapoint from the current dataset
    prediction = model.predict_next(to_predict_from)

    # printing
    print(companies[i])
    print("predicted: " + str(prediction))
    actual_value = values[companies[i]][-1]
    print("actual: " + str(actual_value))
    difference = prediction - values[companies[i]][-1]
    print("difference: " + str(difference))

    relative_errors.append(difference/actual_value)
    i += 1

# listing relative errors made
print("relative errors: ")
print(relative_errors)
print("mean relative error (abs):")
print(np.mean(np.abs(relative_errors)))

